plist.dict:
CFBundleName
{{xml .Name}}
CFBundleExecutable
{{xml .ExeName}}
CFBundleIdentifier
{{xml .AppID}}
CFBundleIconFile
icon.icns
CFBundleShortVersionString
{{xml .Version}}
CFBundleSupportedPlatforms

	MacOSX

CFBundleVersion
{{.Build}}
NSHighResolutionCapable

NSSupportsAutomaticGraphicsSwitching

CFBundleInfoDictionaryVersion
6.0
{{- if .Credit}}
NSHumanReadableCopyright
{{xml .Credit}}
{{- end}}
CFBundlePackageType
APPL
{{- if .Languages}}
CFBundleLocalizations

	{{- range .Languages}}
	{{xml .}}
	{{- end}}

{{- end}}
LSApplicationCategoryType
public.app-category.{{xml .Category}}
LSMinimumSystemVersion
10.11
{{- range .UsageDescriptions}}
{{xml .Key}}
{{xml .Value}}
{{- end}}
{{- if .FileAssociations}}
CFBundleDocumentTypes

	{{- range .FileAssociations}}

		CFBundleTypeName
		{{xml .Name}}
		CFBundleTypeRole
		{{xml .Role}}
		{{- if .Extensions}}
		CFBundleTypeExtensions

			{{- range .Extensions}}
			{{xml .}}
			{{- end}}

		{{- end}}
		{{- if .MimeTypes}}
		CFBundleTypeMIMETypes

			{{- range .MimeTypes}}
			{{xml .}}
			{{- end}}

		{{- end}}
		{{- if .Icon}}
		CFBundleTypeIconFile
		{{xml .Icon}}
		{{- end}}

	{{- end}}

{{- end}}
{{- if .URLSchemes}}
CFBundleURLTypes


		CFBundleURLName
		{{xml .AppID}}
		CFBundleURLSchemes

			{{- range .URLSchemes}}
			{{xml .}}
			{{- end}}



{{- end}}
